// Station 1.3: Die Taxizentrale führt eine Liste der Taxis im Dienst.
// Taxis kommen dazu und melden sich wieder ab – in beliebiger Reihenfolge.

Liste imDienst = new Liste();
imDienst.add(new Taxi(12, "Stefan"));
imDienst.add(new Taxi(7, "Aylin"));
imDienst.add(new Taxi(3, "Jonas"));
imDienst.add(new Taxi(21, "Mira"));

println("Im Dienst:");
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());

// Gleich oder dasselbe? Hier wird ein NEUES Taxi-Objekt mit gleichem Inhalt gesucht.
println("Ist Taxi 7 im Dienst? " + imDienst.enthaelt(new Taxi(7, "Aylin")));

println("Taxi 7 meldet sich ab.");
imDienst.entfernen(new Taxi(7, "Aylin"));
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());

