/**
 * Ein Taxi der Taxizentrale.
 * TODO 4b (Aufgabe 4): Sobald istGleich im Vertrag steht, verlangt der
 * Compiler die Methode auch hier. Zwei Taxis sind gleich, wenn ihre
 * Schlüsselwerte gleich sind.
 */
public class Taxi implements DatenElement {
   private int nummer;
   private String fahrer;

   public Taxi(int nummer, String fahrer) {
      this.nummer = nummer;
      this.fahrer = fahrer;
   }

   public int getNummer() {
      return nummer;
   }

   public String getFahrer() {
      return fahrer;
   }

   public String gibSchluesselwert() {
      return "Taxi " + nummer;
   }
}

/**
 * Selbsttest der Taxizentrale. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class ListeTest {

   private Knoten kette() {
      // k1 (Taxi 12) -> k2 (Taxi 7) -> k3 (Taxi 3), ohne Liste und ohne add gebaut
      Knoten k1 = new Knoten(new Taxi(12, "Stefan"));
      Knoten k2 = new Knoten(new Taxi(7, "Aylin"));
      Knoten k3 = new Knoten(new Taxi(3, "Jonas"));
      k1.setNachfolger(k2);
      k2.setNachfolger(k3);
      return k1;
   }

   private Liste dreiTaxis() {
      Liste l = new Liste();
      l.add(new Taxi(12, "Stefan"));
      l.add(new Taxi(7, "Aylin"));
      l.add(new Taxi(3, "Jonas"));
      return l;
   }

   @Test
   public void laengeKnotenkette() {
      Assertions.assertEquals(3, kette().laenge(), "Knoten.laenge(): Eine Kette aus drei Knoten muss 3 liefern.");
   }

   @Test
   public void laengeLetzterKnoten() {
      Assertions.assertEquals(1, new Knoten(new Taxi(1, "A")).laenge(), "Knoten.laenge(): Ein einzelner Knoten muss 1 liefern.");
   }

   @Test
   public void laengeLeereListe() {
      Assertions.assertEquals(0, new Liste().laenge(), "Liste.laenge(): Eine leere Liste muss 0 liefern.");
   }

   @Test
   public void addInLeereListe() {
      Liste l = new Liste();
      Assertions.assertTrue(l.add(new Taxi(12, "Stefan")), "Liste.add() muss true zurückgeben.");
      Assertions.assertEquals("Taxi 12", l.alsText(), "Nach einem add() muss genau Taxi 12 in der Liste stehen.");
   }

   @Test
   public void addHaengtHintenAn() {
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", dreiTaxis().alsText(), "add() muss hinten anhängen.");
   }

   @Test
   public void laengeNachAdd() {
      Assertions.assertEquals(3, dreiTaxis().laenge(), "Liste.laenge() nach drei add()-Aufrufen muss 3 sein.");
   }

   @Test
   public void enthaeltGleichesTaxi() {
      Assertions.assertTrue(dreiTaxis().enthaelt(new Taxi(7, "Aylin")), "enthaelt(): Ein neues, aber gleiches Taxi 7 muss gefunden werden.");
   }

   @Test
   public void enthaeltNichtVorhanden() {
      Assertions.assertFalse(dreiTaxis().enthaelt(new Taxi(99, "Zoe")), "enthaelt(): Taxi 99 ist nicht in der Liste.");
   }

   @Test
   public void enthaeltLeereListe() {
      Assertions.assertFalse(new Liste().enthaelt(new Taxi(7, "Aylin")), "enthaelt(): In einer leeren Liste ist nichts enthalten.");
   }

   @Test
   public void entfernenMitte() {
      Liste l = dreiTaxis();
      Assertions.assertTrue(l.entfernen(new Taxi(7, "Aylin")), "entfernen() muss true liefern, wenn Taxi 7 gefunden wurde.");
      Assertions.assertEquals("Taxi 12, Taxi 3", l.alsText(), "Nach entfernen(Taxi 7) bleiben Taxi 12 und Taxi 3.");
   }

   @Test
   public void entfernenErstes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(12, "Stefan"));
      Assertions.assertEquals("Taxi 7, Taxi 3", l.alsText(), "Das erste Taxi muss sich auch abmelden können.");
   }

   @Test
   public void entfernenLetztes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(3, "Jonas"));
      Assertions.assertEquals("Taxi 12, Taxi 7", l.alsText(), "Das letzte Taxi muss sich auch abmelden können.");
   }

   @Test
   public void entfernenNichtVorhanden() {
      Liste l = dreiTaxis();
      Assertions.assertFalse(l.entfernen(new Taxi(99, "Zoe")), "entfernen() muss false liefern, wenn nichts gefunden wird.");
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", l.alsText(), "Die Liste darf sich dann nicht verändern.");
   }
}
